# lib/onetime/cli/completion_command.rb
#
# frozen_string_literal: true

#
# Emits a shell completion script for `ots` (bash, zsh, fish).
#
# The command tree is dynamically discovered (billing/app commands are
# auto-required), so completion is generated by walking the live Dry::CLI
# registry rather than hand-maintaining a list. The output is a STATIC script
# with the full command tree baked in — the completer never shells out to
# `ots`, so Tab is instant and never boots the app.
#
# Regenerate on demand:
#   ots completion bash > /etc/bash_completion.d/ots
#   ots completion zsh  > "${fpath[1]}/_ots"     # or: source <(ots completion zsh)
#   ots completion fish > ~/.config/fish/completions/ots.fish
#
# In the OCI image the bash script is baked at build time; see the Dockerfile.
#
# POSIX sh (dash) has no programmable completion facility, so it is not
# supported — an interactive `/bin/sh` user gets completion by running bash.
#
# Usage:
#   ots completion [bash|zsh|fish]
#

module Onetime
  module CLI
    class CompletionCommand < DelayBootCommand
      SUPPORTED = %w[bash zsh fish].freeze

      desc 'Generate a shell completion script (bash, zsh, fish)'

      argument :shell,
        required: false,
        default: 'bash',
        desc: 'Target shell: bash, zsh, or fish'

      def call(shell: 'bash', **)
        case shell
        when 'bash' then puts bash_script
        when 'zsh'  then puts zsh_script
        when 'fish' then puts fish_script
        when 'sh', 'dash', 'posix'
          warn 'POSIX sh has no programmable completion; use bash, zsh, or fish.'
          exit 1
        else
          warn "Unsupported shell: #{shell} (supported: #{SUPPORTED.join(', ')})"
          exit 1
        end
      end

      private

      # Newline-separated list of every non-hidden command path, e.g.
      #   "billing"
      #   "billing catalog drift"
      def command_paths
        registry = Onetime::CLI.instance_variable_get(:@commands)
        root     = registry.instance_variable_get(:@root)
        out      = []
        walk(root, [], out)
        out.sort.uniq
      end

      def walk(node, prefix, out)
        (node.instance_variable_get(:@children) || {}).each do |name, child|
          path = prefix + [name]
          out << path.join(' ') unless child.instance_variable_get(:@hidden)
          walk(child, path, out)
        end
      end

      # The shared completion algorithm, expressed once per shell:
      #   1. Rebuild the subcommand path typed so far, skipping the program
      #      name and any flags/arguments starting with '-'.
      #   2. From the baked command list, offer the child token that follows
      #      that path (or the top-level token when the path is empty).

      def bash_script
        <<~BASH
          # bash completion for `ots` — generated by `ots completion bash`.
          # Static command tree; the completer never invokes ots, so Tab is instant.
          _ots_commands='#{command_paths.join("\n")}'

          _ots_complete() {
            local cur cword words i w path prefix line rest candidates
            cur="${COMP_WORDS[COMP_CWORD]}"
            words=("${COMP_WORDS[@]}")
            cword=$COMP_CWORD

            path=()
            for ((i = 1; i < cword; i++)); do
              w="${words[i]}"
              [[ "$w" == -* ]] && continue
              path+=("$w")
            done
            prefix="${path[*]}"

            candidates=()
            while IFS= read -r line; do
              [[ -z "$line" ]] && continue
              if [[ -z "$prefix" ]]; then
                candidates+=("${line%% *}")
              elif [[ "$line" == "$prefix "* ]]; then
                rest="${line#"$prefix" }"
                candidates+=("${rest%% *}")
              fi
            done <<< "$_ots_commands"

            COMPREPLY=($(compgen -W "$(printf '%s\\n' "${candidates[@]}" | sort -u)" -- "$cur"))
          }

          complete -F _ots_complete ots bin/ots ./bin/ots
        BASH
      end

      def zsh_script
        <<~ZSH
          #compdef ots bin/ots
          # zsh completion for `ots` — generated by `ots completion zsh`.
          # Static command tree; the completer never invokes ots, so Tab is instant.
          # Install: source <(ots completion zsh)   (or drop as _ots in your fpath)
          _ots_commands='#{command_paths.join("\n")}'

          _ots_complete() {
            local -a cmds candidates parts
            local w prefix line rest i
            cmds=(${(f)_ots_commands})

            parts=()
            for (( i = 2; i < CURRENT; i++ )); do
              w=$words[i]
              [[ $w == -* ]] && continue
              parts+=$w
            done
            prefix="${(j: :)parts}"

            candidates=()
            for line in $cmds; do
              if [[ -z $prefix ]]; then
                candidates+=${line%% *}
              elif [[ $line == "$prefix "* ]]; then
                rest=${line\#$prefix }
                candidates+=${rest%% *}
              fi
            done

            compadd -- ${(u)candidates}
          }

          (( $+functions[compdef] )) && compdef _ots_complete ots bin/ots
        ZSH
      end

      def fish_script
        commands = command_paths.map { |p| "'#{p}'" }.join(' ')
        <<~FISH
          # fish completion for `ots` — generated by `ots completion fish`.
          # Static command tree; the completer never invokes ots, so Tab is instant.
          # Install: ots completion fish > ~/.config/fish/completions/ots.fish
          function __ots_complete
              set -l cmds #{commands}
              set -l tokens (commandline -opc)
              set -l parts
              for w in $tokens[2..-1]
                  string match -q -- '-*' $w; and continue
                  set -a parts $w
              end
              set -l prefix (string join ' ' $parts)

              for line in $cmds
                  if test -z "$prefix"
                      string split ' ' -- $line | head -n1
                  else if string match -q -- "$prefix *" $line
                      set -l rest (string replace -- "$prefix " '' $line)
                      string split ' ' -- $rest | head -n1
                  end
              end
          end

          complete -c ots -f -a '(__ots_complete)'
        FISH
      end
    end

    register 'completion', CompletionCommand
  end
end
